//! Infrastructure library panel; previews are generated by the placement engine.
use crate::{
    lang::tr,
    library::infra::{
        self,
        geometry::{self, Primitive},
        Placement,
    },
};
use eframe::egui::{self, Color32, RichText, Sense, Stroke, Vec2};

#[derive(Default)]
pub struct InfraPage {
    query: String,
    category: String,
    selected: String,
    p: Placement,
    at: String,
    path: String,
    connect: String,
    port: String,
    own: String,
    confirm: bool,
    update: String,
    message: String,
}
fn run(command: String) {
    std::thread::spawn(move || {
        if let Err(e) = crate::bridge::execute(&command) {
            crate::bridge::error(&e);
        }
    });
}
impl InfraPage {
    pub fn page(&mut self, ui: &mut egui::Ui) {
        ui.heading(tr("Infra-bibliotheek", "Infrastructure library"));
        ui.label(tr(
            "NLCS 5.0.2 · parametrische objecten · gecontroleerde aansluitingen",
            "NLCS 5.0.2 · parametric objects · checked connections",
        ));
        ui.horizontal(|ui| {
            ui.label(tr("Zoeken", "Search"));
            ui.text_edit_singleline(&mut self.query);
            egui::ComboBox::from_id_salt("infra-category")
                .selected_text(if self.category.is_empty() {
                    tr("Alle thema's", "All themes")
                } else {
                    &self.category
                })
                .show_ui(ui, |ui| {
                    ui.selectable_value(
                        &mut self.category,
                        String::new(),
                        tr("Alle thema's", "All themes"),
                    );
                    if let Ok(items) = infra::catalog() {
                        let categories: std::collections::BTreeSet<_> =
                            items.iter().map(|i| &i.category).collect();
                        for c in categories {
                            ui.selectable_value(&mut self.category, c.clone(), c);
                        }
                    }
                });
        });
        let list = match infra::search(&self.query, &self.category) {
            Ok(v) => v,
            Err(e) => {
                ui.colored_label(Color32::RED, e);
                return;
            }
        };
        if !list.iter().any(|i| i.id == self.selected) {
            self.selected = list.first().map(|i| i.id.clone()).unwrap_or_default();
            self.p = Placement::default();
            self.confirm = false;
        }
        ui.horizontal_top(|ui|{
            ui.vertical(|ui|{
                ui.set_width(260.);ui.label(format!("{} {}",list.len(),tr("onderdelen","items")));
                egui::ScrollArea::vertical().id_salt("infra-list").max_height(620.).show(ui,|ui|{
                    for item in &list{if ui.selectable_label(self.selected==item.id,format!("{}\n{}",item.name(),item.category)).clicked(){self.selected=item.id.clone();self.p=Placement::default();self.confirm=false;}}
                });
            });
            ui.separator();
            ui.vertical(|ui|{
                let Ok(item)=infra::find(&self.selected)else{ui.label(tr("Geen onderdelen gevonden","No items found"));return};
                ui.label(RichText::new(item.name()).strong().size(17.));
                preview(ui,item,&self.p);
                egui::ScrollArea::vertical().id_salt("infra-settings").max_height(470.).show(ui,|ui|{
                    egui::Grid::new("infra-params").num_columns(3).show(ui,|ui|{
                        for param in &item.parameters{
                            ui.label(&param.label);let val=self.p.values.entry(param.key.clone()).or_insert(param.default);
                            ui.add(egui::DragValue::new(val).range(param.min..=param.max).speed(if param.unit=="m/m"{0.001}else{0.01}));ui.label(&param.unit);ui.end_row();
                        }
                    });
                    ui.horizontal(|ui|{
                        ui.label(tr("Status","Status"));for status in ["B","N","T","V"]{ui.selectable_value(&mut self.p.status,status.into(),status);}
                        ui.label(tr("Plotschaal 1:","Plot scale 1:"));ui.add(egui::DragValue::new(&mut self.p.scale).range(1.0..=100000.));
                    });
                    if !item.material.is_empty(){ui.label(format!("{}: {}",tr("Materiaal","Material"),item.material));}
                    if let Some(obj)=crate::nlcs::object(item.object_id){ui.label(format!("NLCS: {} / {} / {}",obj.group,obj.name,item.element));}
                    for layer in &item.layers{ui.label(format!("{} · {:.0} mm",layer.material,layer.thickness*1000.));}
                    for warning in &item.conflicts{ui.colored_label(Color32::YELLOW,warning);}
                    if !item.conflicts.is_empty(){ui.checkbox(&mut self.confirm,tr("Bronverschillen beoordeeld; gekozen waarden gebruiken","Source differences reviewed; use chosen values"));}
                    ui.collapsing(tr("Bronnen en geometrie","Sources and geometry"),|ui|{
                        ui.label(tr("Eigen schematische geometrie; geen officiële symboolvorm of technische dimensionering.","Custom schematic geometry; no official symbol shape or engineering design."));
                        for source in &item.sources{ui.label(format!("{} · {} · {}",source.document,source.revision,source.location));}
                    });
                    ui.separator();
                    ui.label(tr("Plaatsing in projectcoördinaten (m)","Placement in project coordinates (m)"));
                    ui.horizontal(|ui|{ui.label("x,y,z");ui.text_edit_singleline(&mut self.at);});
                    if matches!(item.kind.as_str(),"line"|"area"){
                        ui.label(tr("Hoekpunten x,y;x,y;… of wijs punten aan","Vertices x,y;x,y;… or pick points"));ui.text_edit_singleline(&mut self.path);
                    }
                    ui.collapsing(tr("Aansluiten op bestaand bibliotheekobject","Connect to an existing library object"),|ui|{
                        ui.label(tr("Instantie-ID uit GIS_INFRA_INSPECT","Instance ID from GIS_INFRA_INSPECT"));ui.text_edit_singleline(&mut self.connect);
                        ui.horizontal(|ui|{ui.label(tr("Doelpoort","Target port"));ui.text_edit_singleline(&mut self.port);});
                        ui.horizontal(|ui|{ui.label(tr("Eigen poort","Own port"));ui.text_edit_singleline(&mut self.own);});
                        ui.label("in / out / branch / left / right");
                    });
                    let allowed=item.conflicts.is_empty()||self.confirm;
                    ui.horizontal_wrapped(|ui|{
                        if ui.add_enabled(allowed,egui::Button::new(tr("In tekening aanwijzen","Pick in drawing"))).clicked(){run(self.command(item,false));self.message=tr("Wijs punten aan in de tekening; Enter voltooit de plaatsing.","Pick points in the drawing; Enter completes placement.").into();}
                        if ui.add_enabled(allowed&&(!self.at.trim().is_empty()||!self.connect.trim().is_empty()),egui::Button::new(tr("Plaatsen / aansluiten","Place / connect"))).clicked(){run(self.command(item,true));self.message=tr("Plaatsingsopdracht verstuurd; resultaat verschijnt in de CAD-opdrachtregel.","Placement sent; the CAD command line reports the result.").into();}
                    });
                    ui.collapsing(tr("Bestaand object bijwerken","Update an existing object"),|ui|{
                        ui.label(tr("Instantie-ID; gebruik hetzelfde onderdeeltype","Instance ID; use the same item type"));ui.text_edit_singleline(&mut self.update);
                        if ui.add_enabled(!self.update.trim().is_empty()&&allowed,egui::Button::new(tr("Parameters en aangesloten onderdelen bijwerken","Update parameters and connected objects"))).clicked(){
                            let mut cmd=format!("GIS_INFRA_UPDATE INSTANCE={}",self.update.trim());
                            for(k,v)in &self.p.values{cmd.push_str(&format!(" {}={v}",k.to_uppercase()));}
                            if !self.path.trim().is_empty(){cmd.push_str(&format!(" PATH={}",self.path.trim()));}
                            run(cmd);
                        }
                    });
                    if !self.message.is_empty(){ui.label(&self.message);}
                });
            });
        });
    }
    fn command(&self, item: &infra::Item, explicit: bool) -> String {
        let mut cmd = format!(
            "GIS_INFRA_PLACE ITEM={} STATUS={} SCALE={}",
            item.id, self.p.status, self.p.scale
        );
        for (k, v) in &self.p.values {
            cmd.push_str(&format!(" {}={v}", k.to_uppercase()));
        }
        if self.confirm {
            cmd.push_str(" CONFIRM=true");
        }
        if explicit {
            if !self.at.trim().is_empty() {
                cmd.push_str(&format!(" AT={}", self.at.trim()));
            }
            if !self.path.trim().is_empty() {
                cmd.push_str(&format!(" PATH={}", self.path.trim()));
            }
            if !self.connect.trim().is_empty() {
                cmd.push_str(&format!(
                    " CONNECT={} PORT={} OWN={}",
                    self.connect.trim(),
                    if self.port.trim().is_empty() {
                        "out"
                    } else {
                        self.port.trim()
                    },
                    if self.own.trim().is_empty() {
                        "in"
                    } else {
                        self.own.trim()
                    }
                ));
            }
        }
        cmd
    }
}
fn preview(ui: &mut egui::Ui, item: &infra::Item, p: &Placement) {
    let (rect, _) = ui.allocate_exact_size(
        Vec2::new(ui.available_width().max(200.), 190.),
        Sense::hover(),
    );
    let painter = ui.painter_at(rect);
    painter.rect_filled(rect, 4., ui.visuals().extreme_bg_color);
    let built = match geometry::build(item, p) {
        Ok(v) => v,
        Err(e) => {
            painter.text(
                rect.center(),
                egui::Align2::CENTER_CENTER,
                e,
                egui::FontId::proportional(12.),
                Color32::RED,
            );
            return;
        }
    };
    let mut wires: Vec<Vec<[f64; 2]>> = vec![];
    for part in built.parts {
        match part.geometry {
            Primitive::Poly { points, closed } => {
                let mut v: Vec<_> = points.iter().map(|a| [a[0], a[1]]).collect();
                if closed {
                    if let Some(a) = v.first().copied() {
                        v.push(a);
                    }
                }
                wires.push(v);
            }
            Primitive::Circle { center, radius } => wires.push(
                (0..=48)
                    .map(|k| {
                        let a = k as f64 * std::f64::consts::TAU / 48.;
                        [center[0] + radius * a.cos(), center[1] + radius * a.sin()]
                    })
                    .collect(),
            ),
            Primitive::Hatch { strokes, .. } => {
                for line in strokes {
                    wires.push(line.into_iter().map(|v| [v[0], v[1]]).collect());
                }
            }
            Primitive::Text { .. } => {}
        }
    }
    let mut b = [
        f64::INFINITY,
        f64::INFINITY,
        f64::NEG_INFINITY,
        f64::NEG_INFINITY,
    ];
    for v in wires.iter().flatten() {
        b[0] = b[0].min(v[0]);
        b[1] = b[1].min(v[1]);
        b[2] = b[2].max(v[0]);
        b[3] = b[3].max(v[1]);
    }
    if !b[0].is_finite() {
        return;
    }
    let scale = ((rect.width() - 32.) as f64 / (b[2] - b[0]).max(0.1))
        .min((rect.height() - 32.) as f64 / (b[3] - b[1]).max(0.1));
    let pos = |p: [f64; 2]| {
        egui::pos2(
            rect.center().x + ((p[0] - (b[0] + b[2]) / 2.) * scale) as f32,
            rect.center().y - ((p[1] - (b[1] + b[3]) / 2.) * scale) as f32,
        )
    };
    for line in wires {
        painter.add(egui::Shape::line(
            line.into_iter().map(pos).collect(),
            Stroke::new(1.3, ui.visuals().text_color()),
        ));
    }
    for port in built.ports {
        let a = pos([port.at[0], port.at[1]]);
        painter.circle_filled(a, 3.5, Color32::from_rgb(33, 150, 220));
        painter.text(
            a + Vec2::new(4., -5.),
            egui::Align2::LEFT_BOTTOM,
            port.id,
            egui::FontId::proportional(11.),
            Color32::from_rgb(33, 150, 220),
        );
    }
}
